from typing import Deque, Dict, Tuple

class _ClientState:
    __slots__ = ("last_effective_ts_ms", "records")
    def __init__(self) -> None:
        self.last_effective_ts_ms = 0
        self.records: Deque[Tuple[int, str]] = deque()

class SlidingWindowRateLimiter:
    def __init__(self, limit: int, window_ms: int, max_burst_borrow: int, max_clock_skew_ms: int):
        self.limit = limit
        self.window_ms = window_ms
        self.max_burst_borrow = max_burst_borrow
        self.max_clock_skew_ms = max_clock_skew_ms
        self._clients: Dict[str, _ClientState] = {}
        self._lock = threading.Lock()

    def allow_request(self, client_id: str, node_ts_ms: int, server_recv_ts_ms: int) -> dict:
        with self._lock:
            state = self._clients.get(client_id)
            if state is None:
                state = _ClientState()
                self._clients[client_id] = state

            last_effective = state.last_effective_ts_ms
            skew_clamped = abs(node_ts_ms - server_recv_ts_ms) > self.max_clock_skew_ms
            candidate_ts = server_recv_ts_ms if skew_clamped else node_ts_ms
            effective_ts_ms = max(candidate_ts, last_effective)
