                    "allowed": True,
                    "effective_ts_ms": effective_ts_ms,
                    "borrowed_used": active_borrowed,
                    "remaining_in_window": effective_limit - (active_total + 1),
                    "reason": "CLOCK_SKEW_CLAMPED" if skew_clamped else "OK",
